def score(program: str) -> float:
    # count the real stuff (no spaces), then a lil bonus for raw size
    real_stuff = len(program.replace(" ", "").replace("\n", ""))
    raw_size = len(program)
    x = real_stuff + raw_size / 50
    return x / (x + 3000)

import ast


def score(program: str) -> float:
    try:
        nodes = list(ast.walk(ast.parse(program)))
        kinds = {type(x) for x in nodes}
        return min(1.0, len(kinds) / len(nodes))
    except Exception:
        return 0.0

